sql.where:
game_type = 'zcyltzj'

    AND instance_id = #{instanceId}


    AND school_id = #{schoolId}


    AND point_no = #{pointNo}


    AND scan_time >= #{startDate}


    AND scan_time < #{endDate}


    AND (department_id = #{departmentId}
         OR EXISTS (SELECT 1 FROM gkzh_school_department d
                    WHERE d.department_id = gkzh_zcyltzj_record.department_id
                      AND FIND_IN_SET(#{departmentId}, d.ancestors)))


    AND major LIKE CONCAT('%', #{major}, '%')


    AND student_no LIKE CONCAT('%', #{studentNo}, '%')


    AND gender IN ('男', '0')


    AND gender IN ('女', '1')


    AND (gender IS NULL OR TRIM(gender) = '' OR gender NOT IN ('男', '0', '女', '1'))


    AND status = 'finished'


    AND status <> 'finished'
